// Cloudflare Worker entry: serves the Next.js app (built by OpenNext) and runs the publisher on a schedule.
// @ts-ignore — .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  // Cron Trigger (every minute, see wrangler.jsonc): hand off to the protected cron route.
  async scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    const url = new URL("/api/cron/publish", env.APP_URL || "https://postpilot.internal");
    const res = await handler.fetch(
      new Request(url, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } }),
      env,
      ctx,
    );
    if (!res.ok) console.error("[cron] publish run failed", res.status, await res.text());
  },
} satisfies ExportedHandler<CloudflareEnv>;
